INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'steadily', 'adv.', '/ˈstedɪli/', '平稳地;稳步地', 'The train has been racing steadily across the plateau since dawn.', '火车从黎明起就平稳地驶过高原。', 'Nurturing Nature', 1, 0, 'senior', 'wordlist', 'elective1', 'U6', 'move steadily', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'massive', 'adj.', '/ˈmæsɪv/', '巨大的;大量的', 'Engineers built a massive bridge over the frozen ground.', '工程师在冻土上建造了一座巨大的桥。', 'Nurturing Nature', 2, 0, 'senior', 'wordlist', 'elective1', 'U6', 'a massive bridge', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'delicate', 'adj.', '/ˈdelɪkət/', '脆弱的;娇贵的;精细的', 'The railway was designed to protect the delicate ecosystem of the area.', '这条铁路的设计旨在保护当地脆弱的生态系统。', 'Nurturing Nature', 3, 0, 'senior', 'wordlist', 'elective1', 'U6', 'delicate ecosystem', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'landmark', 'n.', '/ˈlændmɑːk/', '地标;里程碑', 'The Qingshuihe Bridge is a famous landmark on the plateau.', '清水河大桥是高原上著名的地标。', 'Nurturing Nature', 4, 0, 'senior', 'wordlist', 'elective1', 'U6', 'a famous landmark', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'splendid', 'adj.', '/ˈsplendɪd/', '壮丽的;极好的', 'Passengers enjoy the splendid scenery as the train climbs higher.', '火车越爬越高,乘客欣赏着壮丽的景色。', 'Nurturing Nature', 5, 0, 'senior', 'wordlist', 'elective1', 'U6', 'splendid scenery', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'permafrost', 'n.', '/ˈpɜːməfrɒst/', '永久冻土层', 'The bridge was built over permafrost to keep the ground frozen.', '这座桥建在永久冻土层之上,以保持地面冰冻。', 'Nurturing Nature', 6, 0, 'senior', 'wordlist', 'elective1', 'U6', 'built over permafrost', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'antelope', 'n.', '/ˈæntɪləʊp/', '羚羊', 'Groups of antelope move safely under the railway bridges.', '成群的羚羊在铁路桥下安全地走动。', 'Nurturing Nature', 7, 0, 'senior', 'wordlist', 'elective1', 'U6', 'Tibetan antelope', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'leisure', 'n.', '/ˈleʒə/', '空闲;闲暇', 'The wild animals stop to eat grass at their leisure near the line.', '野生动物在铁路旁悠闲地停下来吃草。', 'Nurturing Nature', 8, 0, 'senior', 'wordlist', 'elective1', 'U6', 'at one''s leisure', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'wetland', 'n.', '/ˈwetlənd/', '湿地', 'Workers moved a large wetland to protect its special plants.', '工人们移走了一大片湿地,以保护其中特殊的植物。', 'Nurturing Nature', 9, 0, 'senior', 'wordlist', 'elective1', 'U6', 'protect the wetland', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'grassland', 'n.', '/ˈɡrɑːslænd/', '草原', 'Cattle and sheep wander across the open grassland by the lake.', '牛羊在湖边开阔的草原上漫步。', 'Nurturing Nature', 10, 0, 'senior', 'wordlist', 'elective1', 'U6', 'open grassland', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'radiation', 'n.', '/ˌreɪdiˈeɪʃn/', '辐射', 'High levels of UV radiation made the work very hard for the builders.', '强烈的紫外线辐射让建设者的工作十分艰难。', 'Nurturing Nature', 11, 0, 'senior', 'wordlist', 'elective1', 'U6', 'UV radiation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'wander', 'v.', '/ˈwɒndə/', '漫步;徘徊', 'Sheep wander freely over the grassland beside the railway.', '羊群在铁路旁的草原上自由地漫步。', 'Nurturing Nature', 12, 0, 'senior', 'wordlist', 'elective1', 'U6', 'wander freely', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'scenery', 'n.', '/ˈsiːnəri/', '风景;景色', 'Tourists travel far to enjoy the magical scenery of the plateau.', '游客远道而来,只为欣赏高原上神奇的景色。', 'Nurturing Nature', 13, 0, 'senior', 'wordlist', 'elective1', 'U6', 'magical scenery', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'plateau', 'n.', '/ˈplætəʊ/', '高原', 'The Qinghai-Tibet Plateau has attracted travellers for centuries.', '青藏高原数百年来一直吸引着旅行者。', 'Nurturing Nature', 14, 0, 'senior', 'wordlist', 'elective1', 'U6', 'the high plateau', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'economy', 'n.', '/ɪˈkɒnəmi/', '经济', 'Ecotourism has become an important part of the local economy.', '生态旅游已成为当地经济的重要组成部分。', 'Nurturing Nature', 15, 0, 'senior', 'wordlist', 'elective1', 'U6', 'the local economy', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'jungle', 'n.', '/ˈdʒʌŋɡl/', '(热带)丛林', 'The visitors went on a quiet walk through the green jungle.', '游客们在绿色的丛林中静静地走了一程。', 'Nurturing Nature', 16, 0, 'senior', 'wordlist', 'elective1', 'U6', 'deep jungle', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'disturb', 'v.', '/dɪˈstɜːb/', '干扰;扰乱;打扰', 'Building a hotel here might disturb the wildlife on the beach.', '在这里建酒店可能会扰乱海滩上的野生动物。', 'Nurturing Nature', 17, 0, 'senior', 'wordlist', 'elective1', 'U6', 'disturb the wildlife', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'emission', 'n.', '/ɪˈmɪʃn/', '排放;排放物', 'More cars and planes mean higher carbon emissions every year.', '更多的汽车和飞机意味着每年更高的碳排放。', 'Nurturing Nature', 18, 0, 'senior', 'wordlist', 'elective1', 'U6', 'carbon emission', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'operator', 'n.', '/ˈɒpəreɪtə/', '经营者;操作员', 'The hotel operator promised the design would fit its surroundings.', '酒店经营者承诺其设计会与周围环境相协调。', 'Nurturing Nature', 19, 0, 'senior', 'wordlist', 'elective1', 'U6', 'hotel operator', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'conservationist', 'n.', '/ˌkɒnsəˈveɪʃənɪst/', '环境保护主义者;(自然)保护工作者', 'A conservationist wants to protect the turtles that lay eggs here.', '一位环保主义者想保护在这里产卵的海龟。', 'Nurturing Nature', 20, 0, 'senior', 'wordlist', 'elective1', 'U6', 'a young conservationist', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'candidate', 'n.', '/ˈkændɪdət/', '申请者;候选人', 'Each candidate had to make a short video about the reef.', '每位申请者都要制作一段关于珊瑚礁的短视频。', 'Nurturing Nature', 21, 0, 'senior', 'wordlist', 'elective1', 'U6', 'the best candidate', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'applicant', 'n.', '/ˈæplɪkənt/', '申请人', 'Out of thousands of applicants, only eleven were chosen.', '在数千名申请人中,只有十一人入选。', 'Nurturing Nature', 22, 0, 'senior', 'wordlist', 'elective1', 'U6', 'thousands of applicants', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'favour', 'n.', '/ˈfeɪvə/', '支持,赞同;恩惠', 'She spoke in favour of protecting the natural heritage site.', '她发言支持保护这处自然遗产地。', 'Nurturing Nature', 23, 0, 'senior', 'wordlist', 'elective1', 'U6', 'in favour of', '美式拼 favor;美音 /ˈfeɪvər/', 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'advertise', 'v.', '/ˈædvətaɪz/', '做广告;宣传', 'The reef caretaker job was advertised all over the world.', '珊瑚礁看护员的工作被广而告之于全世界。', 'Nurturing Nature', 24, 0, 'senior', 'wordlist', 'elective1', 'U6', 'advertise the job', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'genuine', 'adj.', '/ˈdʒenjuɪn/', '真的,真正的;真诚的', 'People wondered whether it was a genuine job or just a clever advert.', '人们想知道这是一份真实的工作,还是只是一个聪明的广告。', 'Nurturing Nature', 25, 0, 'senior', 'wordlist', 'elective1', 'U6', 'a genuine offer', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'salary', 'n.', '/ˈsæləri/', '薪水;工资', 'The advertisement said the salary was negotiable.', '广告上说薪水可以协商。', 'Nurturing Nature', 26, 0, 'senior', 'wordlist', 'elective1', 'U6', 'a good salary', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'negotiable', 'adj.', '/nɪˈɡəʊʃiəbl/', '可协商的', 'The pay is negotiable, and meals are provided for free.', '薪酬可以协商,而且免费提供三餐。', 'Nurturing Nature', 27, 0, 'senior', 'wordlist', 'elective1', 'U6', 'salary negotiable', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'preference', 'n.', '/ˈprefrəns/', '优先(权);偏爱', 'Preference will be given to those with diving qualifications.', '拥有潜水资格的人将获得优先考虑。', 'Nurturing Nature', 28, 0, 'senior', 'wordlist', 'elective1', 'U6', 'give preference to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'qualification', 'n.', '/ˌkwɒlɪfɪˈkeɪʃn/', '资格;技能条件', 'A diving qualification is useful for this kind of work.', '潜水资格对这类工作很有用。', 'Nurturing Nature', 29, 0, 'senior', 'wordlist', 'elective1', 'U6', 'diving qualification', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'waist', 'n.', '/weɪst/', '腰;腰部', 'With a rope tied around his waist, he clears rubbish from the cliffs.', '他腰间系着绳子,清理悬崖上的垃圾。', 'Nurturing Nature', 30, 0, 'senior', 'wordlist', 'elective1', 'U6', 'around the waist', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'conserve', 'v.', '/kənˈsɜːv/', '保护;节约', 'Ecotourism helps to conserve the environment for the future.', '生态旅游有助于为未来保护环境。', 'Nurturing Nature', 31, 0, 'senior', 'wordlist', 'elective1', 'U6', 'conserve the environment', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'conservation', 'n.', '/ˌkɒnsəˈveɪʃn/', '保护;保存', 'Wildlife conservation is an important part of this project.', '野生动物保护是这个项目的重要部分。', 'Nurturing Nature', 32, 0, 'senior', 'wordlist', 'elective1', 'U6', 'wildlife conservation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'habitat', 'n.', '/ˈhæbɪtæt/', '栖息地;生长地', 'The passages let the animals move safely in their natural habitat.', '这些通道让动物在自己的自然栖息地里安全地走动。', 'Nurturing Nature', 33, 0, 'senior', 'wordlist', 'elective1', 'U6', 'natural habitat', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'ecosystem', 'n.', '/ˈiːkəʊsɪstəm/', '生态系统', 'The team worked hard to protect the delicate ecosystem.', '团队努力保护这个脆弱的生态系统。', 'Nurturing Nature', 34, 0, 'senior', 'wordlist', 'elective1', 'U6', 'a fragile ecosystem', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'pollution', 'n.', '/pəˈluːʃn/', '污染', 'The reef is now under threat from pollution and climate change.', '如今珊瑚礁正受到污染和气候变化的威胁。', 'Nurturing Nature', 35, 0, 'senior', 'wordlist', 'elective1', 'U6', 'from pollution', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'species', 'n.', '/ˈspiːʃiːz/', '物种;种类', 'The reef is home to many species of birds and sea creatures.', '珊瑚礁是许多鸟类和海洋生物的家园。', 'Nurturing Nature', 36, 0, 'senior', 'wordlist', 'elective1', 'U6', 'many species', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'threat', 'n.', '/θret/', '威胁', 'This delicate place is under threat from human activity.', '这个脆弱的地方正受到人类活动的威胁。', 'Nurturing Nature', 37, 0, 'senior', 'wordlist', 'elective1', 'U6', 'under threat', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'coral', 'n.', '/ˈkɒrəl/', '珊瑚', 'The reef is made of living coral growing on dead coral.', '珊瑚礁由生长在死珊瑚上的活珊瑚构成。', 'Nurturing Nature', 38, 0, 'senior', 'wordlist', 'elective1', 'U6', 'living coral', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'reef', 'n.', '/riːf/', '礁;暗礁', 'The Great Barrier Reef can even be seen from outer space.', '大堡礁甚至可以从外太空看到。', 'Nurturing Nature', 39, 0, 'senior', 'wordlist', 'elective1', 'U6', 'the coral reef', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'responsible', 'adj.', '/rɪˈspɒnsəbl/', '负责任的;有责任的', 'Ecotourism encourages people to be responsible travellers.', '生态旅游鼓励人们做负责任的旅行者。', 'Nurturing Nature', 40, 0, 'senior', 'wordlist', 'elective1', 'U6', 'responsible travellers', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'harmony', 'n.', '/ˈhɑːməni/', '和谐;融洽', 'The design should be in harmony with its beautiful surroundings.', '设计应当与美丽的周围环境相协调。', 'Nurturing Nature', 41, 0, 'senior', 'wordlist', 'elective1', 'U6', 'in harmony with', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'surroundings', 'n.', '/səˈraʊndɪŋz/', '周围环境', 'The new hotel must fit in with its natural surroundings.', '新酒店必须与其自然环境融为一体。', 'Nurturing Nature', 42, 0, 'senior', 'wordlist', 'elective1', 'U6', 'natural surroundings', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'overcome', 'v.', '/ˌəʊvəˈkʌm/', '克服;战胜', 'The workers had to overcome many difficult challenges.', '工人们必须克服许多艰巨的挑战。', 'Nurturing Nature', 43, 0, 'senior', 'wordlist', 'elective1', 'U6', 'overcome challenges', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'challenge', 'n.', '/ˈtʃælɪndʒ/', '挑战;艰巨任务', 'The thin air was perhaps the greatest challenge for the workers.', '稀薄的空气也许是工人们面临的最大挑战。', 'Nurturing Nature', 44, 0, 'senior', 'wordlist', 'elective1', 'U6', 'the greatest challenge', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'protect', 'v.', '/prəˈtekt/', '保护;防护', 'We must do all we can to protect the reef.', '我们必须竭尽全力保护珊瑚礁。', 'Nurturing Nature', 45, 0, 'senior', 'wordlist', 'elective1', 'U6', 'protect the reef', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'aware', 'adj.', '/əˈweə/', '意识到的;知道的', 'People all over the world became aware of the beauty of the ocean.', '全世界的人都意识到了海洋之美。', 'Nurturing Nature', 46, 0, 'senior', 'wordlist', 'elective1', 'U6', 'become aware', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'distinct', 'adj.', '/dɪˈstɪŋkt/', '独特的;清晰的;明显不同的', 'They moved the wetland to protect its distinct ecosystem.', '他们移走湿地,以保护其独特的生态系统。', 'Nurturing Nature', 47, 0, 'senior', 'wordlist', 'elective1', 'U6', 'a distinct ecosystem', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'voluntary', 'adj.', '/ˈvɒləntri/', '自愿的;志愿的', 'Some ecotourism holidays involve voluntary work such as planting trees.', '有些生态旅游假期包含植树等志愿工作。', 'Nurturing Nature', 48, 0, 'senior', 'wordlist', 'elective1', 'U6', 'voluntary work', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe1u6.01', '①have/has been doing:从过去持续到现在的动作(for / since / all day 标记)', 'A2', 11, '外研社版选择性必修第一册 U6 — 当句中有 for + 一段时间、since + 起点、all morning 等标记,且动作从过去一直持续到现在仍在进行时,用 have/has been doing(主语单复数定 have/has);此时一般现在/进行/过去时都不能与该时间标记搭配。', 1, 'elective1', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe1u6.02', '②现在完成进行时 vs 现在完成时(强调持续/仍在进行 vs 结果/完成)', 'A2', 11, '外研社版选择性必修第一册 U6 — 当句子强调动作一直在持续、并由此造成现在可见的状态或结果(累/脏/湿/喘气等),用现在完成进行时 have/has been doing;此处现在完成时(have done)因强调''已完成/数量结果''而不合语境,故标答唯一为进行式。', 2, 'elective1', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe1u6.03', '③现在完成进行时 vs 现在进行时(for/since vs now)', 'A2', 11, '外研社版选择性必修第一册 U6 — 带 for/since + 一段时间且动作延续至今,要用 have/has been doing,而不是只表此刻的现在进行时(am/is/are doing);''for two hours / since this morning'' 与现在进行时不搭配,故标答唯一为现在完成进行时。', 3, 'elective1', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'Since the railway opened, Tibetan antelopes ____ these passages every day.', 'have been using', 'are using', 'use', 'used', 'A', 'since the railway opened 表从过去某点持续到现在,动作仍在进行 → have been using;现在进行/一般现在/过去时都无法与 since 从句搭配。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'The train ____ steadily across the plateau since it left Xining.', 'is racing', 'has been racing', 'races', 'raced', 'B', 'since it left Xining 表持续至今 → has been racing(主语 the train 单数用 has)。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'Workers ____ the delicate wetland to a new area since early this morning.', 'are moving', 'move', 'have been moving', 'moved', 'C', 'since early this morning 表从早上持续到现在 → have been moving。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'It ____ over the grassland since dawn, and the ground is soaked now.', 'is raining', 'rains', 'rained', 'has been raining', 'D', 'since dawn + 现在已湿透,动作持续至今 → has been raining。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'Cattle and sheep ____ across the open grassland since sunrise.', 'have been wandering', 'are wandering', 'wander', 'wandered', 'A', 'since sunrise 表持续至今 → have been wandering。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'Engineers ____ the massive bridge over the permafrost since last spring.', 'are building', 'have been building', 'build', 'built', 'B', 'since last spring 表从去年春天一直到现在 → have been building。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'Water birds ____ in the clear lake since we arrived this afternoon.', 'are playing', 'play', 'have been playing', 'played', 'C', 'since we arrived 表持续至今 → have been playing。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'Ben ____ about the reef on television since June.', 'is speaking', 'speaks', 'spoke', 'has been speaking', 'D', 'since June 表从六月持续到现在 → has been speaking。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'The conservationists ____ the turtles'' nests since sunrise.', 'have been watching', 'are watching', 'watch', 'watched', 'A', 'since sunrise 表持续至今 → have been watching。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'She ____ for the island job ever since the advertisement appeared.', 'is hoping', 'has been hoping', 'hopes', 'hoped', 'B', 'ever since the advertisement appeared 表持续至今 → has been hoping。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'Volunteers ____ trees on the bare hillside since breakfast.', 'are planting', 'plant', 'have been planting', 'planted', 'C', 'since breakfast 表持续至今 → have been planting。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'The guardian ____ the famous pine tree since he was a young man.', 'is protecting', 'protects', 'protected', 'has been protecting', 'D', 'since he was a young man 表从年轻持续至今 → has been protecting。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'For the last twenty minutes, I ____ the headset to explore the rain forest.', 'have been using', 'am using', 'use', 'used', 'A', 'for the last twenty minutes 表到现在为止的一段持续 → have been using。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'Tourists ____ the splendid scenery ever since the train began to climb.', 'are enjoying', 'have been enjoying', 'enjoy', 'enjoyed', 'B', 'ever since the train began to climb 表持续至今 → have been enjoying。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'The Panda Nanny ____ the young pandas since early this morning.', 'is feeding', 'feeds', 'has been feeding', 'fed', 'C', 'since early this morning 表持续至今 → has been feeding。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'Scientists ____ the reef''s delicate ecosystem since the 1970s.', 'are studying', 'study', 'studied', 'have been studying', 'D', 'since the 1970s 表从上世纪七十年代持续至今 → have been studying。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'He ____ rubbish from the steep cliffs since nine o''clock.', 'has been clearing', 'is clearing', 'clears', 'cleared', 'A', 'since nine o''clock 表持续至今 → has been clearing。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'Local people ____ against the new beach hotel since the plan was announced.', 'are arguing', 'have been arguing', 'argue', 'argued', 'B', 'since the plan was announced 表持续至今 → have been arguing。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'The oxygen stations ____ the railway workers healthy since the line opened.', 'are keeping', 'keep', 'have been keeping', 'kept', 'C', 'since the line opened 表持续至今 → have been keeping。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.01'), 'Passengers ____ across the high plateau since the railway opened.', 'are travelling', 'travel', 'travelled', 'have been travelling', 'D', 'since the railway opened 表持续至今 → have been travelling。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'Look at the workers'' muddy boots — they ____ in the wetland all morning.', 'have been working', 'have worked', 'are working', 'worked', 'A', '靴子沾泥是持续活动留下的现在结果,强调动作一直在进行 → have been working;现在完成时 have worked 强调''已完成'',不合此处''活动造成现状''的语境。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'The Panda Nanny looks exhausted because she ____ the heavy cubs since dawn.', 'has carried', 'has been carrying', 'is carrying', 'carried', 'B', 'exhausted 是持续动作造成的现在状态,强调''一直在抱'' → has been carrying。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'Ben is out of breath because he ____ up the cliff for the last ten minutes.', 'has climbed', 'is climbing', 'has been climbing', 'climbed', 'C', '喘不过气是持续攀爬造成的现在结果 → has been climbing。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'Your raincoat is wet through — you ____ in the rain forest, haven''t you?', 'have walked', 'are walking', 'walked', 'have been walking', 'D', '湿透是持续活动的现在结果,强调过程 → have been walking。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'I wonder how long the volunteers ____ trees out on the hillside today.', 'have been planting', 'have planted', 'are planting', 'planted', 'A', 'how long 询问动作持续多久,强调过程 → have been planting。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'The guardian''s hands are dirty because he ____ the mountain path all afternoon.', 'has cleared', 'has been clearing', 'is clearing', 'cleared', 'B', '手脏是持续清理留下的现在结果 → has been clearing。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'The lake water is muddy because the machines ____ near the shore for hours.', 'have dug', 'are digging', 'have been digging', 'dug', 'C', '湖水变浑是持续作业造成的现在结果 → have been digging。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'Rachel is tired but happy; she ____ rhinos at the reserve all day.', 'has counted', 'is counting', 'counted', 'has been counting', 'D', 'tired 是一整天持续活动造成的现在状态,强调过程 → has been counting。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'The conservationists'' eyes are red because they ____ at screens for hours.', 'have been staring', 'have stared', 'are staring', 'stared', 'A', '眼睛红是长时间盯屏幕造成的现在结果 → have been staring。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'My arms ache because I ____ sandbags down to the lake all morning.', 'have carried', 'have been carrying', 'am carrying', 'carried', 'B', '胳膊酸是持续搬运造成的现在结果 → have been carrying。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'The grass is flat over there, where the antelopes ____ all night.', 'have rested', 'are resting', 'have been resting', 'rested', 'C', '草被压平是动物整夜持续停留留下的现在痕迹 → have been resting。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'She is covered in dust because she ____ the red cliffs since lunchtime.', 'has climbed', 'is climbing', 'climbed', 'has been climbing', 'D', '满身灰尘是持续攀爬造成的现在结果 → has been climbing。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'The hotel operator sounds annoyed; the locals ____ with him for weeks.', 'have been arguing', 'have argued', 'are arguing', 'argued', 'A', '强调争论持续了数周仍在进行,造成他现在的恼火 → have been arguing。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'Look how green the rooftops are now — the city ____ gardens up there for years.', 'has grown', 'has been growing', 'is growing', 'grew', 'B', '屋顶现在很绿是多年持续种植的结果,强调持续过程 → has been growing。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'I feel dizzy because I ____ the virtual reality headset for far too long.', 'have used', 'am using', 'have been using', 'used', 'C', '头晕是长时间持续使用造成的现在结果 → have been using。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'The train windows are dusty because we ____ through dry land all day.', 'have travelled', 'are travelling', 'travelled', 'have been travelling', 'D', '车窗积尘是一整天持续穿行造成的现在结果 → have been travelling。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'Everyone on the platform is wet because it ____ over the plateau since noon.', 'has been raining', 'has rained', 'is raining', 'rained', 'A', '大家淋湿是从中午持续下雨造成的现在结果 → has been raining。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'Why are your gloves so dirty? You ____ in the tree nursery again, I see.', 'have worked', 'have been working', 'are working', 'worked', 'B', '手套脏是持续劳作造成的现在结果,强调过程 → have been working。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'The volunteers look sunburnt because they ____ trees in the open sun all day.', 'have planted', 'are planting', 'have been planting', 'planted', 'C', '晒伤是一整天持续户外活动造成的现在结果 → have been planting。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.02'), 'He is breathing hard because he ____ along the railway line for an hour.', 'has run', 'is running', 'ran', 'has been running', 'D', '喘气是持续奔跑造成的现在结果,强调过程 → has been running。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'The conservationist ____ the antelopes through her telescope for over an hour.', 'has been watching', 'is watching', 'watches', 'watched', 'A', 'for over an hour 表持续一小时多至今 → has been watching;现在进行时只表此刻,不能带 for + 时间段。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'We ____ for the train at this lonely station since noon.', 'are waiting', 'have been waiting', 'wait', 'waited', 'B', 'since noon 表从中午等到现在 → have been waiting;现在进行时不与 since 搭配。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'It ____ heavily over the wetland since this morning.', 'is raining', 'rains', 'has been raining', 'rained', 'C', 'since this morning 表持续至今 → has been raining。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'Rachel and her dad ____ about their holiday plans for the last two hours.', 'are talking', 'talk', 'talked', 'have been talking', 'D', 'for the last two hours 表持续两小时至今 → have been talking。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'The team ____ the new bridge since the start of the year.', 'has been building', 'is building', 'builds', 'built', 'A', 'since the start of the year 表从年初持续至今 → has been building。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'I ____ for this island job ever since I first saw the advert.', 'am hoping', 'have been hoping', 'hope', 'hoped', 'B', 'ever since I first saw the advert 表持续至今 → have been hoping。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'Look at the lake — the workers ____ sandbags along it for weeks.', 'are stacking', 'stack', 'have been stacking', 'stacked', 'C', 'for weeks 表持续数周至今 → have been stacking;现在进行时不能带 for + 时间段。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'The pandas ____ in the sun since the gate opened this morning.', 'are sleeping', 'sleep', 'slept', 'have been sleeping', 'D', 'since the gate opened 表持续至今 → have been sleeping。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'Ben ____ photos of the reef for his weekly blog since April.', 'has been taking', 'is taking', 'takes', 'took', 'A', 'since April 表从四月持续至今 → has been taking。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'Scientists ____ the delicate coral for signs of damage for months.', 'are checking', 'have been checking', 'check', 'checked', 'B', 'for months 表持续数月至今 → have been checking。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'The guardian ____ up and down the mountain path since sunrise.', 'is walking', 'walks', 'has been walking', 'walked', 'C', 'since sunrise 表持续至今 → has been walking。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'Volunteers ____ rubbish out of the jungle since early this morning.', 'are carrying', 'carry', 'carried', 'have been carrying', 'D', 'since early this morning 表持续至今 → have been carrying。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'Tourists ____ along the famous railway for the whole afternoon.', 'have been travelling', 'are travelling', 'travel', 'travelled', 'A', 'for the whole afternoon 表持续整个下午至今 → have been travelling。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'My grandfather ____ this art of caring for trees for fifty years.', 'is practising', 'has been practising', 'practises', 'practised', 'B', 'for fifty years 表持续五十年至今 → has been practising。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'The two sides ____ over the beach hotel since the meeting began.', 'are arguing', 'argue', 'have been arguing', 'argued', 'C', 'since the meeting began 表持续至今 → have been arguing。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'She ____ rhinos at the nature reserve since breakfast.', 'is counting', 'counts', 'counted', 'has been counting', 'D', 'since breakfast 表持续至今 → has been counting。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'The machines ____ near the shore since early today.', 'have been running', 'are running', 'run', 'ran', 'A', 'since early today 表持续至今 → have been running。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'People ____ to protect this reef for many years now.', 'are trying', 'have been trying', 'try', 'tried', 'B', 'for many years now 表持续多年至今 → have been trying。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'The river ____ more slowly ever since the new dam was built.', 'is flowing', 'flows', 'has been flowing', 'flowed', 'C', 'ever since the new dam was built 表持续至今 → has been flowing。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U6' AND code='fe1u6.03'), 'The Zhuang people ____ in harmony with this land for hundreds of years.', 'are living', 'live', 'lived', 'have been living', 'D', 'for hundreds of years 表持续数百年至今 → have been living;现在进行时不能带 for + 时间段。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'The Sky Railway', 'The Qinghai-Tibet Railway is often called the "Sky Railway", and it is easy to see why. Many foreign experts once said that building a line across the roof of the world would be impossible. Yet workers from all over China came together to make it real. The railway crosses high mountains, frozen ground and wide grassland, climbing past five thousand metres above the sea. At Tanggula, travellers reach the highest railway station anywhere on the planet. Up there the air is thin, the weather changes quickly, and the sunlight is strong, so the builders faced some of the hardest conditions they had ever met. To keep everyone well, they set up stations that made extra oxygen and gave the crews regular rest in lower places. Today the train races steadily across the plateau, and passengers from every part of the country have been enjoying scenery that once seemed beyond reach. The line shows what careful planning and hard work can achieve.', '说明·青藏铁路', 161, '[{"q":"Why was the railway once thought to be impossible to build?","answer":"A","options":["It had to cross such high and difficult land.","There were no workers willing to help.","No trains were fast enough to use it.","The government had no money for it."],"explanation":"全文说要翻越世界屋脊的高山冻土,环境极难 → 概括为''要穿越如此高而艰险的地带'';其余文中未提或相反。"},{"q":"What made Tanggula Station special?","answer":"B","options":["It was the busiest station in China.","It sat higher than any other railway station on Earth.","It was built underground for safety.","It was the first station ever opened."],"explanation":"原文''the highest railway station anywhere on the planet''的转述。"},{"q":"How did the builders keep the crews healthy in the thin air?","answer":"A","options":["They made extra oxygen and rested in lower areas.","They worked only at night.","They wore special clothes all the time.","They drank large amounts of hot tea."],"explanation":"原文造氧站+到低处休息的转述。"}]'::jsonb, '[{"word":"plateau","cn":"高原"},{"word":"oxygen","cn":"氧气"},{"word":"grassland","cn":"草原"}]'::jsonb, 2, 'elective1', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Room for the Antelopes', 'When the Sky Railway was planned, one big worry was how to keep the wild animals safe. The land it crosses is the natural habitat of Tibetan antelopes, which travel long distances each year to give birth and raise their young. A railway can easily cut such a journey in two, leaving animals trapped on one side. To solve this, the builders left thirty-three passages under the line so that the antelopes could go on moving as freely as before. At first the shy animals were afraid of the strange new structures and would not go near them. The workers waited patiently and changed nothing, and slowly the antelopes learned that the passages were safe. Now the animals have been using these crossings for years, and they hardly seem to notice the trains rushing past above. Wetlands and grassland along the route were also protected with care. The story shows that a great project and healthy wildlife can share the same land.', '说明·野生动物通道', 162, '[{"q":"Why could a railway be dangerous for the antelopes?","answer":"B","options":["It would make too much noise for them to sleep.","It could block the long journeys they make each year.","It would use up all the grass they eat.","It would bring hunters close to them."],"explanation":"原文铁路会把迁徙路线切断、把动物困在一边的转述。"},{"q":"How did the antelopes react to the passages at first?","answer":"C","options":["They used them straight away.","They tried to break them down.","They were frightened and stayed away from them.","They moved to another country."],"explanation":"原文''were afraid… would not go near them''的转述。"},{"q":"What does the writer want to show with this story?","answer":"D","options":["That wild animals should be kept in zoos.","That building railways is always harmful.","That antelopes are too shy to survive.","That big projects and wildlife can exist together."],"explanation":"末句''a great project and healthy wildlife can share the same land''的转述。"}]'::jsonb, '[{"word":"habitat","cn":"栖息地"},{"word":"antelope","cn":"羚羊"},{"word":"passage","cn":"(动物通行的)通道"}]'::jsonb, 2, 'elective1', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'The Best Job in the World', 'A few years ago, an unusual advertisement appeared around the globe. It offered the chance to spend six months living on a beautiful island and looking after the Great Barrier Reef. The working hours were flexible, a place to stay was provided, and the main duties were exploring the area and telling the world about it through blogs, photos and short videos. People wondered whether it was a genuine job or just a clever way to draw attention to the reef. Either way, the idea worked: thousands of applicants from many countries sent in short videos showing how much they knew and why they were the right person. In the end, only eleven were chosen for interviews, and the post went to a young man from Britain named Ben. He spent his months blogging, taking pictures and speaking on television in defence of the reef. He later joked that the job should have been called the busiest, not the best, job in the world.', '记叙·大堡礁看护员', 164, '[{"q":"What was the main work of the island caretaker?","answer":"A","options":["To explore the reef and share it through blogs and videos.","To build new hotels along the coast.","To stop all visitors from coming.","To study fish in a laboratory."],"explanation":"原文探索该地+用博客照片视频对外宣传的转述。"},{"q":"Why did so many people apply for the job?","answer":"B","options":["Because no skills were needed at all.","Because the advertisement was attractive and known worldwide.","Because it paid no money but was easy.","Because they were forced to by their schools."],"explanation":"原文广告吸引全球、上千人申请的转述。"},{"q":"Why did Ben joke about the job''s name?","answer":"C","options":["Because he disliked the reef.","Because he never had to work.","Because the work actually kept him very busy.","Because he was paid too little."],"explanation":"末句他开玩笑说应叫''最忙''而非''最好''的转述,说明实际很忙。"}]'::jsonb, '[{"word":"applicant","cn":"申请人"},{"word":"genuine","cn":"真正的"},{"word":"reef","cn":"珊瑚礁"}]'::jsonb, 2, 'elective1', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'What Is Ecotourism?', 'Ecotourism is a kind of travel that tries to care for nature instead of harming it. The idea is simple: people can still enjoy wild and beautiful places, but they should do so as responsible visitors. Good ecotourism teaches travellers about the natural world and asks them to leave it just as they found it. In countries such as Costa Rica, Kenya and Nepal, this type of tourism has become an important part of the economy, bringing jobs to people who live near forests, mountains and rivers. Some holidays of this kind even include voluntary work. Instead of only lying on a beach, visitors might spend a morning planting young trees or counting rare animals to help scientists. Of course, every trip still has some cost for nature, because cars and planes produce emissions. Yet supporters believe that, done well, ecotourism gives people a reason to protect wild places rather than destroy them, and that is surely worth a great deal.', '说明·生态旅游', 161, '[{"q":"What is the basic aim of ecotourism?","answer":"D","options":["To keep all tourists out of wild places.","To make as much money as possible quickly.","To build large hotels in every forest.","To let people travel while caring for nature."],"explanation":"首句''cares for nature instead of harming it''+做负责任游客的转述。"},{"q":"Why is ecotourism important for countries like Kenya and Nepal?","answer":"A","options":["It brings work to people living near wild areas.","It removes the need for any farming.","It stops anyone from visiting at all.","It makes the weather more pleasant."],"explanation":"原文成为经济重要部分、给森林山河附近的人带来工作的转述。"},{"q":"What do supporters believe ecotourism does best?","answer":"B","options":["It removes all cost to nature.","It encourages people to look after nature instead of ruining it.","It replaces every other kind of holiday.","It ends the use of cars and planes."],"explanation":"末句生态旅游给人保护荒野的理由的转述;A 与文中''仍有一些代价''相反。"}]'::jsonb, '[{"word":"ecotourism","cn":"生态旅游"},{"word":"responsible","cn":"负责任的"},{"word":"voluntary","cn":"志愿的"}]'::jsonb, 2, 'elective1', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Guardians of Nature', 'Across China, ordinary people give their days to looking after the natural world, and three of them tell their stories here. On Mount Huangshan, one man calls himself the Guardian of the Pine Tree. His task is to watch over a single famous tree, checking it several times a day and writing down what he sees. He sometimes feels lonely, but he finds the work deeply rewarding. Far away, on the red cliffs of Mount Yuntai, another worker describes himself as a kind of spiderman. With a rope tied around his waist, he climbs up and down the rock face to clear away the rubbish that careless visitors leave behind. The job carries real danger, yet he is proud to help keep the mountain clean. The third is known as the Panda Nanny of Wolong. She cares for the pandas in a nature reserve, talks with visitors and posts updates online, hoping that one day more people will join her in protecting these gentle animals.', '记叙·自然守护者', 165, '[{"q":"What does the Guardian of the Pine Tree do every day?","answer":"C","options":["He plants new trees on the mountain.","He sells photos of the tree to tourists.","He checks one famous tree and records what he notices.","He cuts the tree''s branches for wood."],"explanation":"原文一天查看几次并记录观察的转述。"},{"q":"Why does the second worker need a rope around his waist?","answer":"D","options":["To carry his lunch up the mountain.","To catch animals on the rocks.","To tie the trees together.","To climb the steep cliffs while clearing rubbish."],"explanation":"原文系绳爬上下崖壁清理垃圾的转述。"},{"q":"What does the Panda Nanny hope for?","answer":"A","options":["That more people will help look after the pandas.","That the reserve will be closed soon.","That she can stop working with pandas.","That visitors will stop coming."],"explanation":"末句希望有更多人加入保护熊猫的转述。"}]'::jsonb, '[{"word":"guardian","cn":"守护者"},{"word":"waist","cn":"腰"},{"word":"reserve","cn":"保护区"}]'::jsonb, 2, 'elective1', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'A Debate over White Beach', 'As more visitors arrive each year, the people of one small city are arguing about their coast. The question is whether a company should be allowed to build a hotel at White Beach. The owner of the company is firmly in favour of the plan. He says a smart new hotel would attract more tourists, create opportunities for fresh businesses and provide many jobs for families in the area. He also promises that the design will sit in harmony with the lovely surroundings. Local people are not so sure. They worry that the work is not eco-friendly and may disturb the wildlife, in particular the turtles that lay their eggs on the sand. Some of them admit that the hotel would help the local economy, yet they fear it might still spoil the very beauty that brings visitors in the first place. They also point out that more tourists mean more cars and planes, and so higher carbon emissions. The two sides have not yet reached an agreement.', '议论·建酒店之争', 168, '[{"q":"Why does the company owner support building the hotel?","answer":"B","options":["He wants to move the turtles somewhere else.","He thinks it will bring jobs and new business to the area.","He plans to live in the hotel himself.","He hopes to stop tourists from coming."],"explanation":"原文吸引游客、创造商机、提供就业的转述。"},{"q":"What are the local people most worried about?","answer":"C","options":["That the hotel will be too small.","That the design will look too modern.","That the work may harm the wildlife, especially the turtles.","That no tourists will come at all."],"explanation":"原文担心不环保、扰乱产卵海龟的转述。"},{"q":"What is the situation between the two sides at the end?","answer":"D","options":["They have happily agreed to build it.","They have decided never to discuss it again.","They have asked tourists to decide for them.","They still have not come to any agreement."],"explanation":"末句双方尚未达成一致的转述。"}]'::jsonb, '[{"word":"in favour of","cn":"支持"},{"word":"disturb","cn":"干扰"},{"word":"emission","cn":"排放物"}]'::jsonb, 2, 'elective1', 'U6', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U6', 'A Journey on the Sky Railway', 'Sitting back in my seat, I could hardly believe that I was finally riding the famous Sky Railway. For years people had told me this line was (1)____ to build, yet here it was, carrying me across the roof of the world. The train raced (2)____ across the high plateau, and the (3)____ outside my window was more beautiful than any photo. Soon we crossed a (4)____ bridge, the longest one ever built over frozen ground. Below it, a group of antelopes were eating grass at their (5)____, taking no notice of us. I learned that special passages had been left so that the animals could keep their (6)____ safe. Higher up, the air grew (7)____, and I felt a little dizzy. Luckily, oxygen was provided to help passengers stay (8)____. At Tanggula we reached the highest station on the whole (9)____. As I looked out at the snow and sky, I felt proud that workers had managed to (10)____ such difficult conditions to build this amazing railway.', 168, 2, '[{"q":"1","answer":"A","options":["impossible","cheap","famous","ready"],"explanation":"people had said the line was impossible to build 不可能修建。"},{"q":"2","answer":"B","options":["loudly","steadily","angrily","rarely"],"explanation":"raced steadily 平稳地行驶。"},{"q":"3","answer":"C","options":["price","noise","scenery","salary"],"explanation":"the scenery outside my window 窗外的风景。"},{"q":"4","answer":"D","options":["tiny","cheap","empty","massive"],"explanation":"a massive bridge 巨大的桥。"},{"q":"5","answer":"A","options":["leisure","danger","speed","duty"],"explanation":"at their leisure 悠闲地。"},{"q":"6","answer":"B","options":["ticket","habitat","engine","garden"],"explanation":"keep their habitat safe 保护栖息地。"},{"q":"7","answer":"C","options":["warm","sweet","thin","heavy"],"explanation":"the air grew thin 空气变得稀薄。"},{"q":"8","answer":"D","options":["angry","famous","rich","healthy"],"explanation":"stay healthy 保持健康。"},{"q":"9","answer":"A","options":["planet","garden","market","machine"],"explanation":"the highest station on the whole planet 全球最高的车站。"},{"q":"10","answer":"B","options":["forget","overcome","waste","sell"],"explanation":"overcome difficult conditions 克服艰难条件。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U6', 'The Ranger and the Antelopes', 'My name is Dawa, and for years I have worked as a ranger on the high (1)____, watching over the Tibetan antelopes. When the railway was first planned, many of us were (2)____ about the animals. We feared that the line would cut their long journey in (3)____ and leave them trapped. To our relief, the builders left thirty-three (4)____ under the railway so the antelopes could still move freely. At first the shy animals would not go (5)____ them, and I worried they never would. But the workers were (6)____ and changed nothing. Slowly, the antelopes began to trust the new crossings. Now they (7)____ across to the grassland to give birth, just as their mothers did. They hardly seem to (8)____ the trains that rush past above. Protecting their (9)____ has become my life''s work, and it makes me proud. I truly believe that a great railway and healthy (10)____ can share the same land.', 157, 2, '[{"q":"1","answer":"C","options":["ocean","street","plateau","ceiling"],"explanation":"the high plateau 高原。"},{"q":"2","answer":"D","options":["glad","bored","proud","worried"],"explanation":"we were worried about the animals 担心。"},{"q":"3","answer":"A","options":["two","tune","time","turn"],"explanation":"cut their journey in two 一分为二。"},{"q":"4","answer":"B","options":["tickets","passages","engines","markets"],"explanation":"thirty-three passages 三十三条通道。"},{"q":"5","answer":"C","options":["away","above","near","behind"],"explanation":"would not go near them 不肯靠近。"},{"q":"6","answer":"D","options":["angry","lazy","noisy","patient"],"explanation":"the workers were patient 耐心。"},{"q":"7","answer":"A","options":["wander","drive","sail","fly"],"explanation":"wander across to the grassland 漫步到草原。"},{"q":"8","answer":"B","options":["sell","notice","drive","paint"],"explanation":"hardly seem to notice the trains 注意到。"},{"q":"9","answer":"C","options":["price","salary","habitat","ticket"],"explanation":"protecting their habitat 保护栖息地。"},{"q":"10","answer":"D","options":["traffic","weather","machinery","wildlife"],"explanation":"healthy wildlife 健康的野生动物。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U6', 'Applying for the Reef Job', 'When I saw the advertisement, I knew at once that I had to (1)____. A company was looking for someone to spend six months looking after the Great Barrier (2)____. The working hours were flexible, and a place to stay was (3)____ for free. The main (4)____ were to explore the islands and tell the world about them through blogs and videos. Some people thought it was not a (5)____ job, just a clever way to draw attention to the reef. I did not care; the chance was too good to (6)____. Each (7)____ had to make a short video showing how much they knew about the area. Out of thousands of people, only eleven were (8)____ for interviews. In the end the (9)____ went to a young man from Britain, but I never regretted trying. Working to (10)____ such a beautiful place would have been a dream come true.', 150, 2, '[{"q":"1","answer":"A","options":["apply","sleep","refuse","leave"],"explanation":"I had to apply 申请。"},{"q":"2","answer":"B","options":["Road","Reef","Roof","River"],"explanation":"the Great Barrier Reef 大堡礁。"},{"q":"3","answer":"C","options":["refused","broken","provided","sold"],"explanation":"a place to stay was provided 提供住处。"},{"q":"4","answer":"D","options":["prices","noises","tickets","duties"],"explanation":"the main duties 主要职责。"},{"q":"5","answer":"A","options":["genuine","noisy","cheap","sleepy"],"explanation":"not a genuine job 不是真实的工作。"},{"q":"6","answer":"B","options":["buy","miss","wash","carry"],"explanation":"too good to miss 好得不容错过。"},{"q":"7","answer":"C","options":["engine","ticket","applicant","garden"],"explanation":"each applicant 每位申请人。"},{"q":"8","answer":"D","options":["thrown","eaten","washed","chosen"],"explanation":"only eleven were chosen 入选。"},{"q":"9","answer":"A","options":["job","rain","snow","song"],"explanation":"the job went to a young man 工作给了……。"},{"q":"10","answer":"B","options":["destroy","protect","sell","forget"],"explanation":"working to protect such a place 保护。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U6', 'A Holiday that Helps Nature', 'Last summer my family chose a very different kind of (1)____. Instead of lying on a busy beach, we joined an ecotourism trip that promised to (2)____ for nature rather than harm it. Our guide taught us to be (3)____ travellers who leave a place just as they find it. In a green (4)____, we walked quietly so as not to (5)____ the wildlife. One morning we did some (6)____ work, planting young trees on a bare hillside. Another day we helped scientists (7)____ rare birds. Our guide explained that this kind of tourism brings jobs and supports the local (8)____. Of course, the planes that carried us there still produced some (9)____, so the trip was not perfect. Even so, I came home believing that travel done this way gives people a real reason to (10)____ wild places instead of spoiling them.', 143, 2, '[{"q":"1","answer":"C","options":["machine","market","holiday","lesson"],"explanation":"a different kind of holiday 假期。"},{"q":"2","answer":"D","options":["shout","pay","fall","care"],"explanation":"care for nature 关爱自然。"},{"q":"3","answer":"A","options":["responsible","lazy","angry","hungry"],"explanation":"responsible travellers 负责任的旅行者。"},{"q":"4","answer":"B","options":["office","jungle","kitchen","stadium"],"explanation":"in a green jungle 丛林。"},{"q":"5","answer":"C","options":["thank","follow","disturb","paint"],"explanation":"not to disturb the wildlife 打扰。"},{"q":"6","answer":"D","options":["careless","foreign","musical","voluntary"],"explanation":"voluntary work 志愿工作。"},{"q":"7","answer":"A","options":["count","sell","cook","hide"],"explanation":"help scientists count rare birds 数。"},{"q":"8","answer":"B","options":["garden","economy","machine","weather"],"explanation":"supports the local economy 经济。"},{"q":"9","answer":"C","options":["flowers","tickets","emissions","songs"],"explanation":"produced some emissions 排放物。"},{"q":"10","answer":"D","options":["destroy","sell","forget","protect"],"explanation":"a reason to protect wild places 保护。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U6', 'A Day as the Panda Nanny', 'People call me the Panda Nanny, and I (1)____ after the pandas in a nature reserve in Sichuan. My day begins early, long before the visitors (2)____. First I prepare food and feed the youngest pandas, which are still too (3)____ to look after themselves. These gentle animals are a rare (4)____, and every one of them matters. Later I clean their homes and check that each panda is (5)____. When visitors come, I (6)____ to them about how we protect these animals and why their (7)____ in the mountains must be kept safe. In the evening I post (8)____ online with photos, so that people far away can follow our work. The job can be tiring, but it is hugely (9)____. My greatest hope is that one day more people will (10)____ me in caring for the pandas, so that these animals will always have a home.', 148, 2, '[{"q":"1","answer":"A","options":["look","throw","sell","fall"],"explanation":"look after the pandas 照顾。"},{"q":"2","answer":"B","options":["refuse","arrive","sleep","cook"],"explanation":"before the visitors arrive 到达。"},{"q":"3","answer":"C","options":["rich","tall","young","loud"],"explanation":"too young to look after themselves 太小。"},{"q":"4","answer":"D","options":["machine","ticket","market","species"],"explanation":"a rare species 稀有物种。"},{"q":"5","answer":"A","options":["healthy","angry","empty","foreign"],"explanation":"check that each panda is healthy 健康。"},{"q":"6","answer":"B","options":["throw","talk","drive","wash"],"explanation":"I talk to them about… 交谈。"},{"q":"7","answer":"C","options":["price","noise","home","salary"],"explanation":"their home in the mountains 家园。"},{"q":"8","answer":"D","options":["engines","tickets","prices","updates"],"explanation":"post updates online 发更新。"},{"q":"9","answer":"A","options":["rewarding","boring","useless","empty"],"explanation":"hugely rewarding 很有意义。"},{"q":"10","answer":"B","options":["leave","join","sell","lose"],"explanation":"more people will join me 加入。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U6', 'Should We Save White Beach?', 'There is a heated argument in our city about White Beach. A company wants to build a large hotel there, and the owner is strongly in (1)____ of the plan. He says the hotel would (2)____ more tourists, create new (3)____ for local businesses and provide many jobs. He also promises that the design will be in (4)____ with the beautiful surroundings. Many local people, however, are (5)____. They worry that the work is not eco-friendly and may (6)____ the wildlife, especially the turtles that lay their eggs on the sand. Some admit that the hotel would help the local economy, yet they fear it could (7)____ the very beauty that draws visitors here. More tourists would also mean more cars and planes, and therefore higher carbon (8)____. As a young (9)____, I believe we should think carefully before we change this coast forever. Once the wildlife is gone, no amount of money can ever (10)____ it back.', 158, 2, '[{"q":"1","answer":"C","options":["danger","front","favour","charge"],"explanation":"in favour of the plan 支持。"},{"q":"2","answer":"D","options":["refuse","sell","cook","attract"],"explanation":"attract more tourists 吸引。"},{"q":"3","answer":"A","options":["opportunities","mistakes","noises","tickets"],"explanation":"create new opportunities 机会。"},{"q":"4","answer":"B","options":["danger","harmony","silence","fashion"],"explanation":"in harmony with the surroundings 和谐。"},{"q":"5","answer":"C","options":["delighted","sleepy","doubtful","hungry"],"explanation":"local people are doubtful 怀疑。"},{"q":"6","answer":"D","options":["thank","follow","paint","disturb"],"explanation":"disturb the wildlife 干扰。"},{"q":"7","answer":"A","options":["spoil","build","save","clean"],"explanation":"spoil the very beauty 破坏。"},{"q":"8","answer":"B","options":["flowers","emissions","songs","tickets"],"explanation":"higher carbon emissions 碳排放。"},{"q":"9","answer":"C","options":["engine","ticket","conservationist","market"],"explanation":"as a young conservationist 环保主义者。"},{"q":"10","answer":"D","options":["throw","sell","lose","bring"],"explanation":"no money can bring it back 带回来。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U6 听力·对话 Planning an Eco-holiday', '外研社版选择性必修第一册 U6 · dialogue', 3, 'Rachel: Dad, for our holiday I''d love to do something that helps nature.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U6 听力·短文 The Sky Railway', '外研社版选择性必修第一册 U6 · passage', 2, 'The Qinghai-Tibet Railway is often called the Sky Railway.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U6 听力·对话 An Interview for the Reef Job', '外研社版选择性必修第一册 U6 · dialogue', 3, 'Manager: Welcome. So, why do you want to be the caretaker of the reef?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U6 听力·短文 Saving the Antelopes', '外研社版选择性必修第一册 U6 · passage', 2, 'The land near the railway is the home of the Tibetan antelope.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U6 听力·对话 The White Beach Debate', '外研社版选择性必修第一册 U6 · dialogue', 3, 'Mr Lee: I really believe a new hotel at White Beach would be good for our city.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U6 听力·短文 Be a Responsible Traveller', '外研社版选择性必修第一册 U6 · passage', 2, 'Here is some advice for anyone who loves to travel.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (11, 'Write a Job Advertisement for a Nature Guardian(写一则自然守护者的招聘广告)', 'Wanted: A Guardian for Our Nature Reserve', '假设你所在的自然保护区需要招聘一名''自然守护者''。请用英语写一则约80词的招聘广告,内容包括:① 这是什么工作、地点在哪里;② 主要职责(如巡查、保护野生动物、向游客介绍);③ 待遇(如薪水可协商、提供食宿);④ 申请要求与方式。注意:语言简洁清楚,适当用现在完成进行时说明保护区一直在做的工作。', 'Suppose the nature reserve near you needs to hire a "Nature Guardian". Write a job advertisement of about 80 words including: 1) what the job is and where it is; 2) the main responsibilities (e.g. checking the area, protecting wildlife, talking to visitors); 3) the benefits (e.g. salary negotiable, food and accommodation provided); 4) the requirements and how to apply.', '["工作与地点(We are looking for a Nature Guardian at … Reserve.)","主要职责(Your duties would include protecting wildlife and …)","待遇(The salary is negotiable; food and accommodation are provided.)","申请要求与方式(Preference will be given to those with … Apply by …)"]'::jsonb, 70, 100, 'Wanted: A Nature Guardian for Green Valley Reserve! For years our team has been protecting the wild animals and delicate wetlands here, and now we need your help. Your main duties would be checking the area each day, looking after the wildlife and telling visitors how to be responsible travellers. The work is full-time, the salary is negotiable, and food and accommodation are provided. Preference will be given to those who love nature and have outdoor experience. To apply, send a short video to greenvalley@reserve.org before 30 June.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["For years our team has been protecting the wild animals and delicate wetlands here.","Your main duties would be checking the area and looking after the wildlife.","The salary is negotiable, and food and accommodation are provided.","Preference will be given to those who love nature and have outdoor experience."]'::jsonb, '[{"wrong":"We are protecting the wildlife here for years.","correct":"We have been protecting the wildlife here for years.","note":"for years 表持续到现在,要用现在完成进行时,不用现在进行时。"},{"wrong":"The salary are negotiable.","correct":"The salary is negotiable.","note":"salary 是单数,系动词用 is。"},{"wrong":"Preference will give to divers.","correct":"Preference will be given to divers.","note":"preference 是被给予,要用被动语态 be given。"}]'::jsonb, '【招聘广告结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (11, 'elective1', 'U6', '{"title":"现在完成进行时 have/has been doing 速查","intro":"结构:have/has + been + 动词-ing。意义:某动作从过去某时开始、一直持续到现在(可能刚停、也可能还在继续),常强调''持续了多久''或''一直在做''。判断口诀:看到 for / since + 时间,且动作是持续性的、延续到此刻,就用 have/has been doing。","table":{"headers":["对比时态","用法 / 例句"],"rows":[["现在完成进行时","强调持续过程:They have been using these passages for years.(一直在用)"],["现在完成时","强调结果/完成:They have built 33 passages.(已建成,看数量结果)"],["现在进行时","只表此刻:Look! An antelope is crossing now.(就在此刻)"],["标志词","for + 时间段 / since + 起点 / all day / how long / 现在可见的结果(累、湿、脏)"]]},"specialRules":[{"rule":"for/since + 一段时间 + 持续动作 → 用 have/has been doing,不用现在进行时","mark":"I have been waiting for two hours.(× I am waiting for two hours.)"},{"rule":"现在可见的状态/结果由持续动作造成 → 用进行式强调过程","mark":"Your boots are muddy. You have been walking in the wetland.(强调一直在走)"},{"rule":"强调''已完成/做了多少'' → 用现在完成时(done),不用进行式","mark":"I have planted ten trees.(数量结果,不用 have been planting ten trees)"},{"rule":"主语单复数决定 have/has;been 不变","mark":"He has been working / They have been working"}],"why":["现在完成进行时把''过去开始''(完成体)和''持续进行''(进行体)合在一起,所以它既连接到现在,又突出动作一直没停;而现在完成时(have done)更看重那个''结果'',现在进行时(am doing)只锁定''此刻''。"],"gaokaoPoints":["语法填空给出动词原形 + for/since/all day 标记 → 多半填 have/has been doing;注意主谓一致(has/have)。","完成进行 vs 完成:有明确数量或 already/just/yet 看结果用 done;问 how long、强调过程用 been doing。","完成进行 vs 进行:带 for/since 用 been doing,只带 now/at the moment 用 am/is/are doing。"],"examVsReal":[{"exam":"I have been studying English for six years.(考试规范)","real":"I''ve been studying English for six years.","note":"口语里 have/has 常缩写成 ''ve/''s;意义不变。"},{"exam":"It has been raining since this morning.(考试)","real":"It''s been raining all morning.","note":"真实英语里 all morning 与 since this morning 可互换,都表持续到现在。"}]}'::jsonb, 'fltrp');
